WITH exploded AS (SELECT id, plan, effective_from, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_limits) li AS element) SELECT CASE WHEN element >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, plan, COUNT(CASE WHEN plan = 'basic' THEN 1 END) AS basic_count, COUNT_IF(plan = 'enterprise') AS enterprise_events, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list FROM exploded GROUP BY ROLLUP (CASE WHEN element >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END, plan) ORDER BY enterprise_events DESC NULLS FIRST
